            // Update geometry to cover entire viewport
            if (this.waterDropEffect.updateWaterMeshGeometry) {
                this.waterDropEffect.updateWaterMeshGeometry();
            }
        }

        if (this.currentConcept && this.currentConcept.onResize) {
            this.currentConcept.onResize();
