        const deltaTime = (currentTime - this.lastTime) / 1000; // Convert to seconds
        this.lastTime = currentTime;

        // Update water drop effect
        if (this.waterDropEffect) {
            // Update water effect (handles materialization and fade-out)
            this.waterDropEffect.update(deltaTime);

            // Keep the captured scene in sync with camera movement for the entire
            // duration of the effect (including the brief fade-out), so that
            // there is no visible "jump" in camera position when the dim layer disappears.
            if (this.waterDropEffect.waterMesh && 
                this.waterDropEffect.waterMesh.visible && 
                !this.waterDropEffect.isComplete()) {
                this.waterDropEffect.renderSceneToTexture();
            }
        }

        if (this.currentConcept && this.currentConcept.update) {
            this.currentConcept.update();
        }

        // Render WebGL scene
        this.renderer.render(this.scene, this.camera);
    }
}

