+  const double hx1 = (double)HF_At(hf, ix + 1, iz);
+  const double hx0 = (double)HF_At(hf, ix - 1, iz);
+  const double hz1 = (double)HF_At(hf, ix, iz + 1);
+  const double hz0 = (double)HF_At(hf, ix, iz - 1);
